		Relations:        counts.Relations,
		Files:            counts.Files,
		Warnings:         warnings,
		PartialFailures:  header.PartialFailures,
		Capabilities:     header.Capabilities,
		NoEgressVerified: noEgress || indexOpts.skipSem,
		WorktreeMode:     worktreeMode,
		WorktreeHash:     worktreeHash,
