+func validateSemanticRecordPath(record *semanticRecord) error {
+	switch record.RecordType {
+	case "file", "symbol":
+	default:
+		return nil
+	}
+	path := record.semanticPath()
+	if path == "" {
+		return nil
+	}
+	clean, err := validateSemanticProviderPath(path)
+	if err != nil {
