  1672	func findSemanticSymbolsInSQLite(storePath, query string, limit, offset int) ([]semanticRecord, error) {
  1673		db, err := sql.Open("sqlite", storePath)
  1674		if err != nil {
  1675			return nil, err
  1676		}
  1677		defer db.Close()
  1678		literal := strings.ToLower(strings.TrimSpace(query))
  1679		rows, err := db.Query(`SELECT s.id, s.kind, s.name, s.qualified_name, s.file_path, s.start_line, s.end_line, s.signature, s.language, s.stable_id_version
  1680	FROM symbols s
  1681	JOIN symbol_fts f ON f.id = s.id
  1682	WHERE instr(lower(f.text), ?) > 0
  1683	ORDER BY CASE WHEN lower(s.name) = lower(?) THEN 0 WHEN lower(s.qualified_name) = lower(?) THEN 1 ELSE 2 END, s.qualified_name
  1684	LIMIT ? OFFSET ?`, literal, query, query, limit, offset)
  1685		if err != nil {
  1686			return nil, err
  1687		}
  1688		defer rows.Close()
  1689		var results []semanticRecord
  1690		for rows.Next() {
  1691			var record semanticRecord
  1692			record.RecordType = "symbol"
  1693			if err := rows.Scan(&record.ID, &record.Kind, &record.Name, &record.QualifiedName, &record.FilePath, &record.StartLine, &record.EndLine, &record.Signature, &record.Language, &record.StableIDVersion); err != nil {
  1694				return nil, err
  1695			}
  1696			results = append(results, record)
  1697		}
  1698		return results, rows.Err()
  1699	}
