  1701	func findSemanticSymbols(snapshotPath, query string, limit, offset int) ([]semanticRecord, error) {
  1702		f, err := os.Open(snapshotPath)
  1703		if err != nil {
  1704			return nil, fmt.Errorf("open semantic snapshot: %w", err)
  1705		}
  1706		defer f.Close()
  1707		query = strings.ToLower(strings.TrimSpace(query))
  1708		scanner := newSemanticScanner(f)
  1709		first := true
  1710		var results []semanticRecord
  1711		seen := 0
  1712		for scanner.Scan() {
  1713			if first {
  1714				first = false
  1715				continue
  1716			}
  1717			text := bytes.TrimSpace(scanner.Bytes())
  1718			if len(text) == 0 {
  1719				continue
  1720			}
  1721			var record semanticRecord
  1722			if err := json.Unmarshal(text, &record); err != nil {
  1723				return nil, err
  1724			}
  1725			if record.RecordType != "symbol" {
  1726				continue
  1727			}
  1728			fields := []string{record.Name, record.QualifiedName, record.Signature, record.FilePath}
  1729			for _, field := range fields {
  1730				if strings.Contains(strings.ToLower(field), query) {
  1731					if seen < offset {
  1732						seen++
  1733						break
  1734					}
  1735					results = append(results, record)
  1736					seen++
  1737					break
  1738				}
  1739			}
  1740			if len(results) >= limit {
  1741				break
  1742			}
  1743		}
  1744		return results, scanner.Err()
  1745	}
